// The city's texts (city.js) in Spanish, as the sentences take them: server after "El servidor" ("El servidor de la
// ciudad de Brno no responde"), dataName as the subject, capitalised ("… no responde ahora"), dataShort after "los
// datos" ("según los datos de la ciudad de Brno y de OSM"), techMap with its article after "Cargando".
const cap = (s) => s[0].toUpperCase() + s.slice(1);
const own = (name, of, map, data, parking, credit) => ({
  server: of, dataName: cap(map), dataShort: `${data} y de OSM`, techMap: map,
  parkingSource: parking, rulesHead: `Anchos según el Manual de Praga del IPR (C.2), orientativos para ${name}:`, credit,
});
const NATIONAL = "el mapa técnico del ČÚZK";
const TECH_PARKING = "aparcamientos del mapa técnico";
const RUIAN = "RÚIAN © ČÚZK, 2026 (CC BY 4.0, modificado)";
// Outside the Czech Republic (city.js abroad): no technical map, OSM only.
const ABROAD = {
  server: "de OpenStreetMap", dataName: null, dataShort: "de OSM", techMap: null, parkingSource: "estimado según las reglas",
  rulesHead: "Anchos según el Manual de Praga del IPR (C.2), fuera de Chequia solo orientativos:", credit: "",
};
